/** Literal Node hook fixture command; every argument is generated by this test process. */
export function nodeFixtureCommand(script:string,...args:string[]){
 const values=[process.execPath,script,...args];
 const quote=(value:string)=>{if(process.platform==='win32'){if(/[\r\n"%!^]/.test(value))throw Error('fixture_command_path_unavailable');return '"'+value+'"';}return "'"+value.replaceAll("'","'\\''")+"'";};
 return values.map(quote).join(' ');
}
